<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {request,query,errorMessage,isCancelled} from '../../shared/api/client'
import {useAuth} from '../../entities/auth/model'
import type {Callback,Filter} from '../../shared/interfaces'
import {callbackLabels,datetime} from '../../shared/lib/format'
import Icon from '../../shared/ui/Icon.vue'
import Notice from '../../shared/ui/Notice.vue'
import CallFilters from '../../features/filter-builder/CallFilters.vue'
import {emptyFilter,validateFilter} from '../../shared/lib/filter'
import Empty from '../../shared/ui/Empty.vue'
const auth=useAuth(),items=ref<Callback[]>([]),asOf=ref(''),error=ref(''),loading=ref(true),state=ref('unhandled'),workspaceFilter=ref<Filter>(emptyFilter())
let timer:ReturnType<typeof setInterval>|undefined
const filtered=computed(()=>items.value.filter(i=>state.value==='all'||state.value==='unhandled'?state.value==='all'||['open','overdue','uncertain'].includes(i.state):i.state===state.value))
const stats=computed(()=>({open:items.value.filter(i=>i.state==='open').length,overdue:items.value.filter(i=>i.state==='overdue').length,uncertain:items.value.filter(i=>i.state==='uncertain').length}))
async function load(background=false){if(!background)loading.value=true;try{const result=await request<{items:Callback[];as_of:string}>('/callbacks'+query({filter:validateFilter(workspaceFilter.value)}));items.value=result.items;asOf.value=result.as_of;error.value=''}catch(e){if(!isCancelled(e))error.value=errorMessage(e)}finally{loading.value=false}}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load(true)},30000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="page-heading"><div><span class="eyebrow">Ни одно обращение не потеряется</span><h1>Контроль перезвонов</h1><p>Пропущенные обращения, попытки связаться и подтверждённые разговоры.</p></div><div class="heading-actions"><button class="button" @click="load()"><Icon name="refresh" :size="15"/>Обновить</button><RouterLink v-if="auth.isOwner" class="button primary" to="/settings/organization">Настроить правила</RouterLink></div></div><Notice :message="error" kind="error"/><div class="card dashboard-filters"><CallFilters v-model="workspaceFilter" callback-only/><div class="form-actions"><button class="button primary small" @click="load()">Применить интервал</button></div></div><div class="cards-stat-small"><button class="card mini-stat" @click="state='open'"><strong>{{stats.open}}</strong><span>Ожидают связи</span></button><button class="card mini-stat" @click="state='overdue'"><strong style="color:#ba8955">{{stats.overdue}}</strong><span>Срок обработки истёк</span></button><button class="card mini-stat" @click="state='uncertain'"><strong style="color:#a0a9aa">{{stats.uncertain}}</strong><span>Нужно проверить историю</span></button></div><div class="card"><div class="card-header"><div><h3>Обращения под контролем</h3><p>Расчёт на {{datetime(asOf,auth.me?.organization.timezone)}}</p></div><select v-model="state" aria-label="Состояние обращения"><option value="unhandled">Все необработанные</option><option value="open">Ожидают связи</option><option value="overdue">Просрочены</option><option value="uncertain">Неполная история</option><option value="resolved">Обработаны</option><option value="all">Все состояния</option></select></div><Empty v-if="loading" loading/><div v-else-if="filtered.length" class="table-wrap"><table class="data-table"><thead><tr><th>Клиент</th><th>Сотрудник</th><th>Пропущенный звонок</th><th>Связаться до</th><th>Попытки</th><th>Состояние</th><th></th></tr></thead><tbody><tr v-for="item in filtered" :key="item.call_id"><td class="primary-text">{{item.phone||'Скрытый номер'}}</td><td>{{item.employee||'Не назначен'}}</td><td>{{datetime(item.opened_at,auth.me?.organization.timezone)}}</td><td>{{datetime(item.due_at,auth.me?.organization.timezone)}}</td><td>{{item.attempts}}</td><td><span class="badge" :class="item.state==='overdue'?'red':item.state==='resolved'?'teal':item.state==='uncertain'?'outline':'amber'">{{callbackLabels[item.state]||item.state}}</span><small>{{item.reason}}</small></td><td><RouterLink class="text-link" :to="'/calls/'+item.call_id">Открыть →</RouterLink></td></tr></tbody></table></div><Empty v-else title="В этой выборке нет обращений" description="Когда появится необработанный пропущенный звонок, он будет отображён здесь."/></div><p class="token-hint">Попытка дозвона без ответа не закрывает обращение. Ответ IVR или очереди также не подтверждает связь с сотрудником. При неполной истории система показывает неопределённость.</p></template>
